# ============================================================== 1. Исходные страницы → оформление ЦЕХ Стандарт
def rebrand_source():
    doc = pymupdf.open(SRC)
    login = os.path.join(SHOTS, 'pro_max', 'login.png')
    seen = set()
    for pno, page in enumerate(doc):
        for info in page.get_image_info(xrefs=True):
            x = info['xref']
            if x in seen or not x: continue
            seen.add(x)
            f = os.path.join(IMGDIR, 'p%03d_x%d.jpg' % (pno + 1, x))
            if pno + 1 == 13 and os.path.exists(login):
                from PIL import Image
                j = os.path.join(_JPG, 'login.jpg'); Image.open(login).convert('RGB').save(j, quality=85, optimize=True)
                page.replace_image(x, filename=j)
            elif os.path.exists(f): page.replace_image(x, filename=f)
    # цвета в потоках страниц
    for page in doc:
        for x in page.get_contents():
            s = doc.xref_stream(x).decode('latin1')
            t = re.sub(r'(?<![\d.])(\.\d+ \.\d+ \.\d+)(?= (?:rg|RG|sc|SC|scn|SCN)\b)', lambda m: COLOR_MAP.get(m.group(1), m.group(1)), s)
            if t != s: doc.update_stream(x, t.encode('latin1'))
    # колонтитулы и название в тексте
    for pno, page in enumerate(doc):
        fixes = []
        for b in page.get_text('dict')['blocks']:
            if b['type']: continue
            for l in b['lines']:
                t = ''.join(s['text'] for s in l['spans'])
                if l['bbox'][1] > 815:
                    page.add_redact_annot(pymupdf.Rect(l['bbox']) + (-1, -1, 1, 1)); continue
                if 'MON CHEF' in t and pno + 1 >= 13:
                    k = next(i for i, s in enumerate(l['spans']) if 'MON CHEF' in s['text'] or i == len(l['spans']) - 1)
                    sp = l['spans'][k:]
                    r = pymupdf.Rect(sp[0]['bbox'])
                    for s in sp: r |= pymupdf.Rect(s['bbox'])
                    page.add_redact_annot(r + (-0.5, -1, 1, 1))
                    fixes.append(sp)
        page.apply_redactions(images=pymupdf.PDF_REDACT_IMAGE_NONE, graphics=pymupdf.PDF_REDACT_LINE_ART_NONE)
        for sp in fixes: reinsert(page, sp)
    return doc

def font_of(span):
    f = span['font']
    return 'serifb' if 'Serif' in f else 'sansb' if 'Bold' in f or '-B' in f else 'sans'

def reinsert(page, spans):
    items, x = [], spans[0]['origin'][0]
    for i, s in enumerate(spans):
        text = s['text'].replace('MON CHEF', 'ЦЕХ Стандарт')
        fk = font_of(s); size = s['size']
        c = s['color']; rgb = ((c >> 16) & 255) / 255, ((c >> 8) & 255) / 255, (c & 255) / 255
        if c == 0x6e1423: rgb = GOLD
        gap = (spans[i + 1]['bbox'][0] - s['bbox'][2]) if i + 1 < len(spans) else 0
        items.append([text, fk, size, rgb, s['origin'][1], gap, s['size'] < 9.2 and fk == 'sansb'])
    width = lambda k: sum(tlen(t, f, sz * k) + g for t, f, sz, _, _, g, _ in items)
    k = 1.0
    while x + width(k) > 556 and k > 0.75: k -= 0.02
    for t, f, sz, rgb, y, g, chip in items:
        w = tlen(t, f, sz * k)
        if chip:
            page.draw_rect(pymupdf.Rect(x - 2, y - sz * k * 0.85, x + w + 2, y + sz * k * 0.3), color=(0.8039, 0.7333, 0.6039), fill=(1, 1, 1), width=0.6, radius=0.25)
        page.insert_text((x, y), t, fontfile=FONTS[f], fontname=f, fontsize=sz * k, color=rgb)
        x += w + g

