def esc(s): return html.escape(str(s), quote=False)
def chip(t, pri=False): return f'<span class="chip{" pri" if pri else ""}">{t}</span>'
def who(k, g=None, gl='Где'): return f'<div class="who">Кто: {k}</div>' + (f'<div class="who">{gl}: {g}</div>' if g else '')
def steps(items, start=1): return '<ol class="st">' + ''.join(f'<li data-n="{i + start}">{t}</li>' for i, t in enumerate(items)) + '</ol>'
def note(title, text, warn=False): return f'<div class="note{" warn" if warn else ""}"><b class="t">{title}</b>{text}</div>'
_JPG = tempfile.mkdtemp()
def shot(plan, name):
    f = os.path.join(SHOTS, plan, name + '.png')
    if not os.path.exists(f): return ''
    from PIL import Image
    j = os.path.join(_JPG, plan + '_' + name + '.jpg')
    if not os.path.exists(j):
        im = Image.open(f).convert('RGB'); im.thumbnail((1600, 1600), Image.LANCZOS); im.save(j, quality=82, optimize=True)
    return f'<div class="shot"><img src="file://{j}"></div>'
def tbl(head, rows): return '<table><tr>' + ''.join(f'<th>{h}</th>' for h in head) + '</tr>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows) + '</table>'

